import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            key = f\"{name} [{fw['framework']}]\"
            pkgs = {}
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
            result[key] = pkgs
    return result

b = extract(baseline)
a = extract(after)

print('=== VERSION CHANGES ===')
changes = False
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            print(f'  {key}: {pkg} {bv} -> {av}')
            changes = True
if not changes:
    print('  (none - packages resolve identically)')

print()
print('=== UNCHANGED ===')
count = 0
for key in sorted(b.keys()):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(bp.keys()):
        if bp[pkg] == ap.get(pkg):
            count += 1
print(f'  {count} package references unchanged')
